import Foundation

/// PKCS#12 fixtures of the client certificate tests (L-10), generated with the
/// OpenSSL commands below. A and B are two client certificates signed by one test CA.
///
/// - `a`, `b`, `noKey`: `openssl pkcs12 -export -inkey a.key -in a.pem -keypbe PBE-SHA1-3DES
///   -certpbe PBE-SHA1-3DES -macalg sha1 -passout pass:alpha` (B: `bravo`; no key: `-nokeys`).
///   The legacy algorithms every Security version reads.
/// - `modernA`: the same certificate A exported with no algorithm option, i.e. the
///   OpenSSL 3 defaults (PBES2/AES-256-CBC, PBKDF2, MAC SHA-256), which some Apple
///   releases refuse with the right password (`errSecPkcs12VerifyFailure`).
enum ClientCertificateFixtures {
    static let passwordA = "alpha"
    static let passwordB = "bravo"
    static let aBase64 = ""
    static var a: Data { Data(base64Encoded: aBase64)! }
    static let bBase64 = ""
    static var b: Data { Data(base64Encoded: bBase64)! }
    static let noKeyBase64 = ""
    static var noKey: Data { Data(base64Encoded: noKeyBase64)! }
    static let modernABase64 = ""
    static var modernA: Data { Data(base64Encoded: modernABase64)! }
    /// Eight bytes of a PNG: not a PKCS#12.
    static let notPKCS12 = Data([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])
}
